odal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Guardar</button></div></form></div></div></div><script>document.addEventListener('DOMContentLoaded',()=>{document.getElementById('emergencyModal').addEventListener('show.bs.modal',e=>{let d={};try{d=JSON.parse(e.relatedTarget?.dataset.json||'{}')}catch(x){}for(const [id,key,def] of [['emergencyId','id',''],['emergencyCategory','category','security'],['emergencyStatus','status','active'],['emergencyName','name',''],['emergencyPhone','phone',''],['emergencyOrder','sort_order','0'],['emergencyAvailability','availability','']])document.getElementById(id).value=d[key]??def;document.getElementById('emergencyVisible').checked=d.id?!!Number(d.is_visible_to_residents):true;});});</script><?php endif;?>
